const bank = [{"id": "Development-m2-q1", "course": "Development", "module": 2, "prompt": "The systems development lifecycle (SDLC) has six phases. The first three phases are plan, define, and design. What are the last three phases of the SDLC?", "options": ["Develop, deploy, and maintain", "Code, build, and test", "Test, deploy, and maintain", "Code, build, and maintain"], "answers": ["Develop, deploy, and maintain"]}, {"id": "Development-m2-q2", "course": "Development", "module": 2, "prompt": "Which task is performed during the develop stage of the systems development lifecycle (SDLC)?", "options": ["Deficiencies are identified.", "New system requirements are defined.", "New components are obtained and installed.", "The system is put into use."], "answers": ["New components are obtained and installed."]}, {"id": "Development-m2-q3", "course": "Development", "module": 2, "prompt": "A systems administrator must grant a new developer permissions that are associated with the developer role. This role is associated with the developer group. Which AWS service should the administrator use to assign the new developer to the developer group?", "options": ["AWS Identity and Access Management (IAM)", "Amazon Elastic Compute Cloud (Amazon EC2)", "Amazon Simple Storage Service (Amazon S3)", "AWS Resource Access Manager (AWS RAM)"], "answers": ["AWS Identity and Access Management (IAM)"]}, {"id": "Development-m2-q4", "course": "Development", "module": 2, "prompt": "A developer is setting up their development environment. They need an integrated development environment (IDE) that enables them to code with other people in real time. Which AWS service should they use?", "options": ["Amazon CloudWatch", "AWS Cloud9", "Amazon CloudFront", "AWS CloudShell"], "answers": ["AWS Cloud9"]}, {"id": "Development-m2-q5", "course": "Development", "module": 2, "prompt": "What are three ways to interact with AWS service application programming interfaces (APIs)? (Select the THREE best options)", "options": ["AWS Management Console", "AWS Software development kits (SDKs)", "AWS CloudTrail", "AWS Command Line Interface (AWS CLI)", "AWS X-Ray", "AWS Identity and Access Management (IAM)"], "answers": ["AWS Management Console", "AWS Software development kits (SDKs)", "AWS Command Line Interface (AWS CLI)"]}, {"id": "Development-m2-q6", "course": "Development", "module": 2, "prompt": "Which tools enable users to control their AWS services from the command line and automate service management with scripts? (Select THREE)", "options": ["AWS Serverless Application model (AWS SAM)", "AWS Tools for PowerShell", "AWS Cloud9", "AWS X-Ray", "AWS CodeCommit", "AWS Amplify"], "answers": ["AWS Serverless Application model (AWS SAM)", "AWS Tools for PowerShell", "AWS Amplify"]}, {"id": "Development-m2-q7", "course": "Development", "module": 2, "prompt": "True or False: The service client application programming interfaces (APIs) provide a lower level of abstraction than the higher-level calls that are made by resource APIs.", "options": ["True", "False"], "answers": ["True"]}, {"id": "Development-m2-q8", "course": "Development", "module": 2, "prompt": "Which statements describe AWS resource application programming interfaces (APIs)? (Select TWO)", "options": ["They provide a higher-level abstraction than the low-level calls made by service client APIs.", "They provide a lower-level abstraction than the higher-level calls made by the service client APIs.", "They have objects for request and result data.", "They provide access to resources through objects and collections.", "They have at least one class per conceptual resource."], "answers": ["They provide a higher-level abstraction than the low-level calls made by service client APIs.", "They provide access to resources through objects and collections."]}, {"id": "Development-m2-q9", "course": "Development", "module": 2, "prompt": "A developer is using the AWS software development kit (SDK) for Python (Boto3) and must specify the Region. Which method enables the developer to specify the Region?", "options": ["By setting the Region when they instantiate the service client", "By setting the AWS_PROFILE environment variable", "Users cannot specify the AWS Regions in the service client", "By associating a default Region with their profile in the credentials files in the .aws folder within their \"home\" folder."], "answers": ["By setting the Region when they instantiate the service client"]}, {"id": "Development-m2-q10", "course": "Development", "module": 2, "prompt": "A developer makes an application programming interface (API) call to access an Amazon Simple Storage Service (Amazon S3) bucket that doesn't exist. Which HTTP response code does the developer receive from the AWS service?", "options": ["200 Series", "300 Series", "400 Series", "500 Series"], "answers": ["400 Series"]}, {"id": "Development-m2-q4-alt", "course": "Development", "module": 2, "prompt": "Which tool enables users to control their AWS services from the command line and automate service management with scripts?", "options": ["Amazon Q Developer", "AWS Tools for PowerShell", "AWS activity & access management", "AWS X-Ray"], "answers": ["AWS Tools for PowerShell"]}, {"id": "Development-m2-q8-alt", "course": "Development", "module": 2, "prompt": "Which feature provides a key advantage when using AWS CloudShell?", "options": ["It requires users to purchase reserved capacity and time blocks in advance.", "It automatically uses authentication credentials from your AWS Management Console session.", "It provides users with 500 MB of storage in each AWS Region.", "It requires users to manually maintain and update the environment."], "answers": ["It automatically uses authentication credentials from your AWS Management Console session."]}, {"id": "Development-m2-q9-alt", "course": "Development", "module": 2, "prompt": "Which description best explains the purpose of Amazon Q Developer?", "options": ["A fully cloud-hosted integrated development environment (IDE)", "A setup assistant that guides users through configuring an IDEC.", "An AI-powered tool that helps developers write, understand, and improve code", "A command-line interface that runs in a web browser"], "answers": ["An AI-powered tool that helps developers write, understand, and improve code"]}, {"id": "Development-m2-q4-cloudshell", "course": "Development", "module": 2, "prompt": "Which of the following is an important benefit of AWS CloudShell?", "options": ["You manually patch and update the environment.", "You pay up front for reserved blocks of time and capacity.", "Users get 500 MB of storage per region.", "It inherits your credentials from the AWS Management Console."], "answers": ["It inherits your credentials from the AWS Management Console."]}, {"id": "Development-m2-q7-amazon-q", "course": "Development", "module": 2, "prompt": "What is Amazon Q Developer?", "options": ["A wizard that leads you through the steps to configure your integrated development environment (IDE)", "A generative AI-powered coding assistant", "A cloud-based integrated development environment (IDE)", "A browser-based CLI"], "answers": ["A generative AI-powered coding assistant"]}, {"id": "Development-m3-q1", "course": "Development", "module": 3, "prompt": "A student is learning about Amazon Simple Storage Service (Amazon S3). During an interview, a potential employers asks the student to explain how Amazon S3 can be used as a storage solution. Which option is a use case for Amazon S3?", "options": ["Block-level storage", "Hosting active databases", "Shared files systems", "Data lake"], "answers": ["Data lake"]}, {"id": "Development-m3-q2", "course": "Development", "module": 3, "prompt": "A developer wants to store image files in a bucket that is called images-bucket, but receives the error BucketAlreadyExists. Which action must the developer take to resolve this error?", "options": ["Bucket names are globally unique. If the requested bucket name is not available, the developer must rename the bucket.", "Bucket names are unique to the Region that they are created in. If the requested bucket name is not available, the developer must create the images-bucket in a different Region.", "The developer must contact AWS Support to request approval to use the same bucket name.", "Bucket names go to the highest bidder. The developer must outbid the current bucket owner."], "answers": ["Bucket names are globally unique. If the requested bucket name is not available, the developer must rename the bucket."]}, {"id": "Development-m3-q3", "course": "Development", "module": 3, "prompt": "A ______ organizes the Amazon Simple Storage Service (Amazon S3) namespace at the highest level.", "options": ["Container", "Group", "Bucket", "Region"], "answers": ["Bucket"]}, {"id": "Development-m3-q4", "course": "Development", "module": 3, "prompt": "A developer is using Amazon Simple Storage Service (Amazon S3) to host a static website in a bucket called frank-martha-cafe. This bucket is in the us-east-1 Region. Which URL is the virtual-hosted-style URL for their website?", "options": ["https://s3-website-us-east-1.amazonaws.com/frank-martha-cafe", "https://frank-martha-cafe.s3-us-east-1.amazonaws.com", "https://www.frank-martha-cafe.s3-website-us-east-1.amazonaws.com", "https://frank-martha-cafe.s3-website-us-east-1.amazonaws.com"], "answers": ["https://frank-martha-cafe.s3-website-us-east-1.amazonaws.com"]}, {"id": "Development-m3-q5", "course": "Development", "module": 3, "prompt": "True or False: After versioning is enabled on an Amazon Simple Storage Service (Amazon S3) bucket, it can be disabled.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Development-m3-q6", "course": "Development", "module": 3, "prompt": "What is the largest size of an object that a user can upload to Amazon Simple Storage Service (Amazon S3) in a single PUT operation?", "options": ["1 GB", "5 GB", "100 MB", "5 TB"], "answers": ["5 GB"]}, {"id": "Development-m3-q7", "course": "Development", "module": 3, "prompt": "A developer uses an Amazon Simple Storage Service (Amazon S3) bucket. They want to allow a certain AWS Identity and Access Management (IAM) user to perform any S3 operation on the bucket and its objects. They also want to follow AWS recommendations for granting permissions. Which mechanism should the developer apply to the bucket?", "options": ["Bucket access control list (ACL)", "IAM policy", "Cross-Origin resource Sharing (CORS)", "Bucket policy"], "answers": ["Bucket policy"]}, {"id": "Development-m3-q8", "course": "Development", "module": 3, "prompt": "A developer wants to allow a user to download objects directly from an Amazon Simple Storage Service (Amazon S3) bucket without needing AWS security credentials or permissions. What can the developer share with the user to grant them time-limited access to the objects.", "options": ["A presigned URL", "A temporary token", "The bucket endpoint URL", "Their AWS account root user credentials"], "answers": ["A presigned URL"]}, {"id": "Development-m3-q9", "course": "Development", "module": 3, "prompt": "Which method can be used to encrypt Amazon Simple Storage Service (Amazon S3) objects in transit?", "options": ["Server-Side Encryption with Customer-Provided Keys (SSE-C)", "Secure Sockets Layer/Transport Layer Security (SSL/TLS)", "Server-Side Encryption with Amazon S3-Managed Keys (SSE-S3)", "Server-Side Encryption with AWS KMS-Managed Keys (SSE-KMS)"], "answers": ["Secure Sockets Layer/Transport Layer Security (SSL/TLS)"]}, {"id": "Development-m3-q10", "course": "Development", "module": 3, "prompt": "A developer hosts a static website in an Amazon Simple Storage Service (Amazon S3) bucket. The website references image objects in another S3 bucket. However, these images do no display on the website. What could be the problem?", "options": ["Cross-Origin Resource Sharing (CORS) has not been enabled on the bucket where the assets are stored", "Cross-region Replication (CRR) has not been enabled on the bucket where the assets are stored.", "Amazon S3 does not support object sharing between buckets.", "The security group of the S3 bucket does not include an inbound rule to allow HTTP traffic on port 80."], "answers": ["Cross-Origin Resource Sharing (CORS) has not been enabled on the bucket where the assets are stored"]}, {"id": "Development-m4-q1", "course": "Development", "module": 4, "prompt": "Which option is the Amazon Web Services (AWS) customer responsible for under the AWS shared responsibility model? (Select TWO)", "options": ["Security group configuration", "Physical servers", "Client-side data", "Edge location infrastructure", "Availability Zone security"], "answers": ["Security group configuration", "Client-side data"]}, {"id": "Development-m4-q2", "course": "Development", "module": 4, "prompt": "Which AWS Identity and Access Management (IAM) resource explicitly grants or denies permissions to a user or group of users?", "options": ["IAM roles", "IAM users", "IAM groups", "IAM policies"], "answers": ["IAM policies"]}, {"id": "Development-m4-q3", "course": "Development", "module": 4, "prompt": "Which is the correct term for the process of verifying a user's identity as a developer?", "options": ["Endorsement", "Authentication", "Confirmation", "Authorization"], "answers": ["Authentication"]}, {"id": "Development-m4-q4", "course": "Development", "module": 4, "prompt": "Which statements about IAM user authentication are true? (Select TWO)", "options": ["AWS credentials to authenticate with any supported services must be provided.", "A user name and password to authenticate to the console must be provided.", "A .pem or .ppk file is used to authenticate programmatically to the AWS application programming interface (API).", "It is a best practice to use the account root user credentials to authenticate programmatically by using the AWS Command Line Interface (AWS CLI).", "Each AWS account can have only one administrator who manages other IAM users."], "answers": ["AWS credentials to authenticate with any supported services must be provided.", "A user name and password to authenticate to the console must be provided."]}, {"id": "Development-m4-q5", "course": "Development", "module": 4, "prompt": "Which suggestion is an Amazon Web Services (AWS) recommendation for securing AWS credentials for application that run on Amazon Elastic Compute Cloud (Amazon EC2) instances?", "options": ["Embed AWS credentials in the software development kit (SDK) client code.", "Store credentials in local AWS configuration files.", "Create an AWS Identity and Access Management (IAM) role and attach it to the EC2 instance.", "Create an AWS Identity and Access Management (IAM) user and attach it to the EC2 instance."], "answers": ["Create an AWS Identity and Access Management (IAM) role and attach it to the EC2 instance."]}, {"id": "Development-m4-q6", "course": "Development", "module": 4, "prompt": "What is the format of AWS Identity and Access Management (IAM) polices that define the allowable API calls an entity can invoke?", "options": ["YAML Ain't Markup Language (YAML)", "Security Assertion Markup Language (SAML)", "Comma-separated values (CSV)", "Javascript Object Notation (JSON)"], "answers": ["Javascript Object Notation (JSON)"]}, {"id": "Development-m4-q7", "course": "Development", "module": 4, "prompt": "An administrator created an AWS Identity and Access Management (IAM) groups called managers within an AWS account. A ____ policy is attached to the managers group. It allows managers to read from and write to an Amazon Simple Storage Service (Amazon S3) bucket in the same AWS account. What is this type of policy?", "options": ["Identity-based", "Resource-based", "Cross-account access", "AdministratorAccess managed"], "answers": ["Identity-based"]}, {"id": "Development-m4-q8", "course": "Development", "module": 4, "prompt": "Which statement reflects best practices when granting permissions to users, groups, roles, and resources?", "options": ["Create policies that allow broad access and then limit permissions as needed, based on usage.", "Use the account root user for routine tasks that the administrator performs.", "Create policies that follow the principle of least privilege.", "Do not set policies for indivdual resources."], "answers": ["Create policies that follow the principle of least privilege."]}, {"id": "Development-m4-q9", "course": "Development", "module": 4, "prompt": "What is the effect of the following policy statement? { \"Effect\": \"Deny\", \"Action\":[\"dynamodb:\", \"s#:\" ], \"NotResource\": [ \"arn:aws:dynamodb:region:account-number:table/pollynotes\", \"arn:aws:s3:::polly-notes-web\", \"arn:aws:s3:::polly-notes-mp3/*\" ] }", "options": ["Denies actions on DynamoDB or Amazon S3 resources except for the resources that are listed in the NotResource element.", "Denies actions on the DynamoDB table or S3 buckets that are listed in the NotResources element.", "Denies the ability to write to the pollynotes DynamoDB table.", "Denies the ability to read from the polly-notes-web S3 bucket."], "answers": ["Denies actions on DynamoDB or Amazon S3 resources except for the resources that are listed in the NotResource element."]}, {"id": "Development-m4-q10", "course": "Development", "module": 4, "prompt": "Which statements are true about evaluation logic for AWS Identity and Access Management (IAM) policies? (Select TWO)", "options": ["You cannot have deny and allow statements in the same policy.", "An explicit allow overrides an explicit deny.", "An explicit deny overrides an explicit allow.", "By default, all requests are denied.", "By default, all requests are allowed."], "answers": ["An explicit deny overrides an explicit allow.", "By default, all requests are denied."]}, {"id": "Development-m5-q1", "course": "Development", "module": 5, "prompt": "Which statement best describes Amazon DynamoDB?", "options": ["An in-memory data store that can boost the performance of databases", "A graph database engine that is optimized for storing billions of relationships", "A relational database that is built for the cloud and is compatible with the MySQL and PostgreSQL", "A key-value and document database that scales horizontally and works well for internet-scale applications"], "answers": ["A key-value and document database that scales horizontally and works well for internet-scale applications"]}, {"id": "Development-m5-q2", "course": "Development", "module": 5, "prompt": "Which component is part of the Amazon DynamoDB table?", "options": ["Predefined schema", "SQL-based queries", "Attributes", "Columns"], "answers": ["Attributes"]}, {"id": "Development-m5-q3", "course": "Development", "module": 5, "prompt": "An Amazon DynamoDB table called SensorReadings captures sensor readings. These readings include a sensor ID attribute that acts as the partition key, and a timestamp attribute that is the sort key. Which statement is true?", "options": ["The sensor ID together with the timestamp represent a simple primary key.", "It is impossible for two items in the SensorReadings table to have the same partition key.", "It is impossible for two items in the SensorReadings table to have the same sort key.", "It is impossible for two items in the SensorReadings table to have the same primary key."], "answers": ["It is impossible for two items in the SensorReadings table to have the same primary key."]}, {"id": "Development-m5-q4", "course": "Development", "module": 5, "prompt": "Which statement about Amazon DynamoDB partitions is true?", "options": ["DynamoDB stores data in partitions and chooses the partition based on the range attribute.", "If a table has a simple primary key (partition key only), DynamoDB stores and retrieves each item based on its hash attribute.", "If a table has a composite primary key, DynamoDB will sort the items based on the sort key before selecting the partition for the item.", "A developer writes a hash function to tell DynamoDB how to partition the items."], "answers": ["If a table has a simple primary key (partition key only), DynamoDB stores and retrieves each item based on its hash attribute."]}, {"id": "Development-m5-q5", "course": "Development", "module": 5, "prompt": "Suppose that a developer has a restaurants database table that can be queried by name (the partition key), or by name and location (the sort key). What should the developer do if they also want to query by the type of cuisine and average customer rating?", "options": ["Set up a local secondary index on cuisine and customer rating.", "Set up a global secondary index on cuisine and customer rating.", "Change the primary key on the restaurant table to be a complex primary key based on cuisine and customer rating.", "Perform a query that uses the cuisine and average customer rating attributes."], "answers": ["Set up a global secondary index on cuisine and customer rating."]}, {"id": "Development-m5-q6", "course": "Development", "module": 5, "prompt": "A video game developer who sues Amazon DynamoDB wants to ensure that players' profiles are updated correctly when they make in-game purchases. This process requires multiple updates as part of the single user action. What is the best choice tow rite this developer's application to manage these complex, all-or-nothing changes?", "options": ["Add an Amazon DynamoDB Accelerator (DAX) cluster.", "Implement global tables.", "Create application code to check that all parts of the transaction were written successfully, and then roll back the update if any part failed.", "Use DynamoDB transactions."], "answers": ["Use DynamoDB transactions."]}, {"id": "Development-m5-q7", "course": "Development", "module": 5, "prompt": "Which scenarios are example use cases for Amazon DynamoDB Streams? (Select TWO)", "options": ["An application that requires the fastest possible response time for reads to support real-time bidding", "An application that requires repeated reads against a large set of regional weather data to perform a long-running analysis", "An application that automatically sends notifications to the mobile devices of all friends in a group when one friend uploads a new picture", "An application that must monitor changes to a DynamoDB table and take action on specific changes when a value reaches a certain threshold", "An application that requires an in-memory data store"], "answers": ["An application that automatically sends notifications to the mobile devices of all friends in a group when one friend uploads a new picture", "An application that must monitor changes to a DynamoDB table and take action on specific changes when a value reaches a certain threshold"]}, {"id": "Development-m5-q8", "course": "Development", "module": 5, "prompt": "Which statement about global tables is true?", "options": ["Global tables provide a managed solution for replicating tables within a single AWS Region.", "Global tables use Amazon Simple Storage Service (Amazon S3) to propagate changed between replicas.", "When a global table is created, Amazon DynamoDB performs all necessary tasks to create identical tables and propagate ongoing data changes to specified Regions.", "With a global table, Amazon DynamoDB supports partial replication of some of the items in a table."], "answers": ["When a global table is created, Amazon DynamoDB performs all necessary tasks to create identical tables and propagate ongoing data changes to specified Regions."]}, {"id": "Development-m5-q9", "course": "Development", "module": 5, "prompt": "How far in days can an Amazon DynamoDB table be restored by using point-in-time recovery?", "options": ["The last week", "The last 10 days", "The last 35 days", "The last calendar month"], "answers": ["The last 35 days"]}, {"id": "Development-m5-q10", "course": "Development", "module": 5, "prompt": "Which statement describes Amazon DynamoDB application programming interface (API) control operations that can invoked by an application?", "options": ["Create and manage DynamoDB tables.", "Create, read, update, and delete data in a table.", "Get and write batches of items in a DynamoDB table.", "Make coordinated, all-or-nothing changes to multiple items both within and across tables."], "answers": ["Create and manage DynamoDB tables."]}, {"id": "Development-m6-q1", "course": "Development", "module": 6, "prompt": "What phrase best describes a RESTful API?", "options": ["An API that uses HTTP to communicate between client and server", "A proxy that exists between client and server to handle common problems that occur with API-driven applications", "An API that follows the principles of the Representational State Transfer style", "An API that resides on the web server"], "answers": ["An API that follows the principles of the Representational State Transfer style"]}, {"id": "Development-m6-q2", "course": "Development", "module": 6, "prompt": "Which option suggests the use of WebSocket APIs?", "options": ["An order processing application returns an order number to each customer when they submit an order.", "A batch process bundles orders and sends them to a fulfillment center application.", "A real-time chat application lets customers talk to customer support about their orders.", "A reporting application gives the sales team access to static daily reports from their phones."], "answers": ["A real-time chat application lets customers talk to customer support about their orders."]}, {"id": "Development-m6-q3", "course": "Development", "module": 6, "prompt": "Which use case suggests using Amazon API Gateway HTTP APIs?", "options": ["An application needs an API proxy in front of an AWS Lambda function.", "An application must transform a response from as AWS Lambda function before returning the response to the client.", "A developer wants to use mock endpoints to test their API.", "A developer wants to assign different API quotas by client."], "answers": ["An application needs an API proxy in front of an AWS Lambda function."]}, {"id": "Development-m6-q4", "course": "Development", "module": 6, "prompt": "Which statement about Amazon API Gateway integrations is true?", "options": ["A first-class integration connects an API Gateway HTTP API route to an external third-party service API.", "A developer can use HTTP proxy integrations to direct a route to a resource on the internet.", "API Gateway cannot access resources within a virtual private cloud (VPC)", "An API integrations request encapsulates an HTTP request that the backend receives and is always different from the method request that the client submits."], "answers": ["A developer can use HTTP proxy integrations to direct a route to a resource on the internet."]}, {"id": "Development-m6-q5", "course": "Development", "module": 6, "prompt": "An application that uses Amazon API Gateway must capture contact information from the a third-party client application. The client application sends given name, surname, business phone, and cellphone. The backend application database has only two fields: name and mobile phone. Which option requires the fewest application changes?", "options": ["Export the API definition and use it to update the client.", "Use a mapping template to transform the request before it is sent to the database.", "Create a usage plan that describes the fields and applies only to this client.", "Use a first-class integration to connect the client to the database."], "answers": ["Use a mapping template to transform the request before it is sent to the database."]}, {"id": "Development-m6-q6", "course": "Development", "module": 6, "prompt": "Which elements are part of the base URI that AWS generates for an Amazon Gateway API?", "options": ["Region and stage name", "API identifier and version", "Account ID and stage name", "Region and version"], "answers": ["Region and stage name"]}, {"id": "Development-m6-q7", "course": "Development", "module": 6, "prompt": "aws apigatewayv2 create-route \\ --api-id 03z501670a \\ -- <?> -- taget arn:aws:lambda:us-east-2:AcctID:function:readFn Which option could replace the <?> to create an API route that returns an indivdual product value from an online catalog?", "options": ["route-key 'GET /products/{product_id}' \\", "route-key 'PUT /products'", "route-selection-exprsession '$GET/product'", "route-selection-exprsession 'PUT /products/{proxy+}' \\"], "answers": ["route-key 'GET /products/{product_id}' \\"]}, {"id": "Development-m6-q8", "course": "Development", "module": 6, "prompt": "Which statement about Amazon API Gateway stages is true?", "options": ["Stage names are sequentially assigned based on the API version.", "Any stage on any API type can be set to autodeploy.", "Developers can use stage variables to connect different stages to different backends.", "Developers should avoid creating different stages for each development environment."], "answers": ["Developers can use stage variables to connect different stages to different backends."]}, {"id": "Development-m6-q9", "course": "Development", "module": 6, "prompt": "A security team wants to know how to protect APIs in their internet application from common web exploits, like SQL injection or cross-site scripting. Which solution most directly addresses their specific concern?", "options": ["Set throttling limits on their API methods in Amazon API Gateway.", "Set all their APIs to use private endpoints.", "Configure a JSON Web Token (JWT)-based authorizer for Amazon API Gateway.", "Use AWS WAF with Amazon API Gateway."], "answers": ["Use AWS WAF with Amazon API Gateway."]}, {"id": "Development-m6-q10", "course": "Development", "module": 6, "prompt": "What does the Amazon API Gateway integrationLatency metric tell the user?", "options": ["Frequency of server-side errors that affect latency", "Speed of the API response back to the client", "Responsiveness of the backend", "How often requests are throttled"], "answers": ["Responsiveness of the backend"]}, {"id": "Development-m7-q1", "course": "Development", "module": 7, "prompt": "Which statement describes a characteristic of AWS Lambda?", "options": ["Lambda runs code only when it is activated by an event and uses only the compute resources that are needed.", "A developer's methods and configuration options for ensuring high availability with Lambda are similar to their approach with Amazon Elastic Compute Cloud (Amazon EC2)", "Lambda function run in on-demand, temporary environments, and the developer controls when new environments are created or shut down.", "A developer must write Lambda functions that use one of the runtimes that the Lambda service provides."], "answers": ["Lambda runs code only when it is activated by an event and uses only the compute resources that are needed."]}, {"id": "Development-m7-q2", "course": "Development", "module": 7, "prompt": "Which constraint cannot be modified?", "options": ["Function timeout", "Reserved concurrency", "Burst quota", "Regional quota"], "answers": ["Burst quota"]}, {"id": "Development-m7-q3", "course": "Development", "module": 7, "prompt": "Which option best describes how Amazon API Gateway invokes AWS Lambda?", "options": ["API Gateway directly invokes a function with a synchronous invocation.", "Lambda processes API Gateway requests asynchronously and retires each request up to two times.", "Lambda uses an event source mapping and polls API Gateway for requests", "API Gateway directly invokes a function and retires the request until it succeeds or expires."], "answers": ["API Gateway directly invokes a function with a synchronous invocation."]}, {"id": "Development-m7-q4", "course": "Development", "module": 7, "prompt": "Which actions require permissions that are defined in the AWS Lambda execution role? (Select TWO)", "options": ["A Lambda function writes to an Amazon DynamoDB table.", "An object that is written to an Amazon Simple Storage Service (Amazon S3) bucket initiates invocation of a Lambda function.", "Lambda polls an Amazon Simple Queue Service (Amazon SQS) queue for messages that initiate invocation of a Lambda function.", "An Amazon API Gateway GET route initiates invocation of a Lambda function.", "A message that is posted to an Amazon Simple Notification Service (Amazon SNS) topic initiates invocation of Lambda function."], "answers": ["A Lambda function writes to an Amazon DynamoDB table.", "Lambda polls an Amazon Simple Queue Service (Amazon SQS) queue for messages that initiate invocation of a Lambda function."]}, {"id": "Development-m7-q5", "course": "Development", "module": 7, "prompt": "Which statement about the function handler in an AWS Lambda function is true?", "options": ["The function handler is the entry point that Lambda calls to start running the Lambda function.", "The function handler method might take an event object or context object.", "The event object provides information about the event that invoked the Lambda function. It must be predefined object that an AWS services generates.", "The context object provides runtime information, and the developer must create a context object that matches the runtime that was selected for the function."], "answers": ["The function handler is the entry point that Lambda calls to start running the Lambda function."]}, {"id": "Development-m7-q6", "course": "Development", "module": 7, "prompt": "Which issue might be addressed by adding provisioned concurrency to an AWS Lambda function?", "options": ["Another Lambda function runs in the same account and Region. It sometimes spikes and consumes all available concurrency, causing the function to fail.", "An application that uses the Lambda function responds slowly for the first few users who sign in each day. Lambda metrics show higher latency for those initial requests.", "A legacy backend system fails intermittently when the developer connects to it. To avoid extra costs, they want to reduce the function's wait time when the backend fails.", "The developer wants more visibility into transactions that use the Lambda function to identify bottlenecks."], "answers": ["An application that uses the Lambda function responds slowly for the first few users who sign in each day. Lambda metrics show higher latency for those initial requests."]}, {"id": "Development-m7-q7", "course": "Development", "module": 7, "prompt": "Which AWS Lambda configuration setting might be a developer use to manage function errors when configuring an Amazon Simple Notification Service (Amazon SNS) topic as the event source for a Lambda function? (Select TWO)", "options": ["State machines", "File Systems", "Destinations", "Virtual private cloud", "Asynchronous invocations"], "answers": ["Destinations", "Asynchronous invocations"]}, {"id": "Development-m7-q8", "course": "Development", "module": 7, "prompt": "A zipped deployment package including code and custom libraries is 75MB in size. Which AWS Lambda deployment option should be used?", "options": ["Copy the code into the Lambda console editor to create and deploy the function.", "Upload a .zip file from an integrated development environment (IDE) to load the deployment package directly into the Lambda console.", "Upload the deployment package to an Amazon Simple Storage Service (Amazon S3) bucket, and specify the bucket name and object key on the Lambda console.", "Upload the deployment package to an Amazon Elastic Block Store (Amazon EBS) volume, and us the File Systems configuration to reference it."], "answers": ["Upload the deployment package to an Amazon Simple Storage Service (Amazon S3) bucket, and specify the bucket name and object key on the Lambda console."]}, {"id": "Development-m7-q9", "course": "Development", "module": 7, "prompt": "A function's Amazon Resource Name (ARN) is as follows: arn:aws:lambda:aws-region:acct-id:function:helloworld:PROD Which statement about this function is correct, based on its ARN?", "options": ["This ARN will invoke the immutable PROD version of the function.", "This ARN will invoke the version of the function that is currently associated with the PROD alias.", "This ARN will invoke the function and include the AWS Lambda layer that is named PROD", "This ARN will deploy the helloworld function into the PROD account."], "answers": ["This ARN will invoke the version of the function that is currently associated with the PROD alias."]}, {"id": "Development-m7-q10", "course": "Development", "module": 7, "prompt": "Users of a serverless application have reported errors that occur when they try to retrieve order information. Assuming that AWS X-Ray is enabled, what is the first step the developer might take in X-Ray to start troubleshooting the reported issues quickly?", "options": ["Drill down into the most recent traces to look for errors.", "Search for metadata that is related to the users who are reporting issues.", "Add annotations that the developer can sue to start grouping and filtering traces.", "Use the service map to visually locate errors across the application."], "answers": ["Use the service map to visually locate errors across the application."]}, {"id": "Development-m8-q1", "course": "Development", "module": 8, "prompt": "Which options describes a benefit that led the shipping industry and the software industry to use containers?", "options": ["Infrastructure providers can create strong dependencies between their platform and the types of containers that they choose to work with.", "The abstraction of details of what's being \"shipped\" increases the agility of a system.", "Increased visibility into the details of what's being \"shipped\" helps each point in the system to provide the right type of support.", "The ability to use nonstandard types of containers gives producers flexibility."], "answers": ["The abstraction of details of what's being \"shipped\" increases the agility of a system."]}, {"id": "Development-m8-q2", "course": "Development", "module": 8, "prompt": "Which options are components of a container? (Select TWO)", "options": ["Host server", "Runtime engine", "Operating system", "Application code", "Virtual machine"], "answers": ["Runtime engine", "Application code"]}, {"id": "Development-m8-q3", "course": "Development", "module": 8, "prompt": "Which statement about Docker containers is true?", "options": ["A container is a runnable instance of an image.", "A container registry is a template to launch containers.", "A container image is a writable template.", "A container layer is a thin read-only later that is associated with a running container."], "answers": ["A container is a runnable instance of an image."]}, {"id": "Development-m8-q4", "course": "Development", "module": 8, "prompt": "Which Docker CLI command creates a container named my_app_1 from the image named node_app?", "options": ["docker run --name my_app_1 node_app", "docker build --tag my_app_1", "docker exec -it my_app_1 sh", "docker images my_app_1 from node_app"], "answers": ["docker run --name my_app_1 node_app"]}, {"id": "Development-m8-q5", "course": "Development", "module": 8, "prompt": "Which statement about Dockerfile is true?", "options": ["A Dockerfile is a YAML file that provides instructions to create a container image.", "Each instruction in a Dockerfile creates a read-only layer in the image.", "If a developer changes the Dockerfile and rebuilds the image, all layers of the image must be rebuilt.", "Developers cannot use the Dockerfile to run scripts that would run after the container is instantiated."], "answers": ["Each instruction in a Dockerfile creates a read-only layer in the image."]}, {"id": "Development-m8-q6", "course": "Development", "module": 8, "prompt": "A developer wants to migrate a monolithic shopping website to a microservice-based application. Which option reflects a reason to choose containers?", "options": ["Each container can use the language and technology that are best suited for the service.", "Containerized components are not isolated, so the application will evolve as a singular system.", "Containers are well-suited to designs that avoid the use of temporary resources.", "Containers separate your dependencies and libraries into their own objects."], "answers": ["Each container can use the language and technology that are best suited for the service."]}, {"id": "Development-m8-q7", "course": "Development", "module": 8, "prompt": "A developer recently built a proof-of-concept application using containers, and the business owner wants to roll it out to production. Which option reflects a primary reason that the developer might use a container orchestration service?", "options": ["To schedule container starts and stops and determine where to place containers.", "To base their containers on third-party images.", "To remove the requirement to use a container registry.", "To receive automated recommendations about how to improve their application code to run on containers."], "answers": ["To schedule container starts and stops and determine where to place containers."]}, {"id": "Development-m8-q8", "course": "Development", "module": 8, "prompt": "Which statement about the Amazon Elastic Container Service (Amazon ECS) is true?", "options": ["Amazon ECS is a highly scalable container orchestration services that supports Docker containers.", "Amazon ECS requires the use of Amazon Elastic Container Registry (Amazon ECR) for container images.", "Amazon ECS supports launching containers in Amazon EC2 or AWS Lambda", "With Amazon ECS, you can deploy applications to containers even if they have not been architected specifically to run on containers."], "answers": ["Amazon ECS is a highly scalable container orchestration services that supports Docker containers."]}, {"id": "Development-m8-q9", "course": "Development", "module": 8, "prompt": "What is the name of a logical collection of AWS Elastic Beanstalk components, which is conceptually similar to a folder?", "options": ["Environment", "Platform", "Application", "Environment tier"], "answers": ["Application"]}, {"id": "Development-m8-q10", "course": "Development", "module": 8, "prompt": "A developer wants to do canary testing on a new deployment. Which AWS Elastic Beanstalk deployment policy option should the developer use?", "options": ["Immutable", "Rolling with batch", "Traffic Splitting", "Blue/Green"], "answers": ["Traffic Splitting"]}, {"id": "Development-m9-q1", "course": "Development", "module": 9, "prompt": "A developer had been asked whether caching might improve the performance of their online bidding application. How should they answer the question?", "options": ["Caching probably will not yield much performance improvement for this type of application.", "Caching might improve performance by reducing the number of hits to the backend database. However, caching cannot improve performance issues that occur between the client and web server.", "Using different types of caching at each application layer might improve both the frontend and backend performance.", "Caching might greatly improve performance if the application is compute heavy, but if the application is read heavy, a cache will not provide much benefit."], "answers": ["Using different types of caching at each application layer might improve both the frontend and backend performance."]}, {"id": "Development-m9-q2", "course": "Development", "module": 9, "prompt": "An architect suggests that the developers implement caching on an existing application to address performance issues. Which option describes factors that the developers should consider when they decide where to add caching?", "options": ["Avoid caching for data queries that are slow and expensive to run.", "Review the data and its access patterns, Data that changes rapidly but is infrequently accessed should be cached.", "Consider the tolerance for stale data in each context where the data is used.", "Add as much caching in as many places as you can as early in development as possible."], "answers": ["Consider the tolerance for stale data in each context where the data is used."]}, {"id": "Development-m9-q3", "course": "Development", "module": 9, "prompt": "A developer has to determine that an in-memory key-value store would improve performance of their application's queries. They want to keep the solution as simple as possible and need to support read replicas. Which options should they choose?", "options": ["Amazon ElastiCache for Memcached", "Amazon ElastiCache for Redis", "Amazon CloudFront Functions", "Lambda@Edge"], "answers": ["Amazon ElastiCache for Redis"]}, {"id": "Development-m9-q4", "course": "Development", "module": 9, "prompt": "Amazon ElastiCache is being added to an application to improve response times and alleviate database pressure. The backend database for application is an Amazon Relational Database Service (Amazon RDS) database. Which task would be the responsibility of the application developer?", "options": ["Applying software patches to the cache instances", "Writing code to check the health of the cluster before writing to the cache", "Writing code that looks for the requested data in the cache and, if the data is not found, requests it from the origin", "Write code to integrate the cache with the Amazon RDS instances that will be reading from"], "answers": ["Writing code that looks for the requested data in the cache and, if the data is not found, requests it from the origin"]}, {"id": "Development-m9-q5", "course": "Development", "module": 9, "prompt": "Which statement about Amazon ElastiCache is true?", "options": ["A node is a variable-size chunk of secure, network-attached RAM.", "Your application connects to an ElastiCache node by using a unique address called an endpoint.", "With the Memcached engine, data is partitioned across shards in a cluster.", "Every node within a cluster must run the same cache engine, but the node can run on different instance types."], "answers": ["Your application connects to an ElastiCache node by using a unique address called an endpoint."]}, {"id": "Development-m9-q6", "course": "Development", "module": 9, "prompt": "A developer has been asked to address complaints from customers in the London area about the performance of a web-based application that is hosted in New York. Which option might the developer implement?", "options": ["Use Amazon CloudFront to replicate the application code on Amazon Elastic Compute Cloud (Amazon EC2) instances in the London Region.", "Set up a CloudFront distribution that can serve static content from the edge locations that are closer to UK users.", "Set up a CloudFront regional edge location in the London Region.", "Set up one CloudFront edge location in New York and one in London."], "answers": ["Set up a CloudFront distribution that can serve static content from the edge locations that are closer to UK users."]}, {"id": "Development-m9-q7", "course": "Development", "module": 9, "prompt": "A developer has been asked to increase the cache hit ratio for their Amazon CloudFront distribution. Which option should they try?", "options": ["Include only the minimum necessary values in the cache key.", "Decrease the maximum time to live (TTL) setting in a cache policy.", "Decrease the max-age setting in a file's Cache-Control header.", "Increase the cache hit setting in a cache policy."], "answers": ["Include only the minimum necessary values in the cache key."]}, {"id": "Development-m9-q8", "course": "Development", "module": 9, "prompt": "Which statement about Amazon CloudFront cached file expiration is true?", "options": ["Each file in the cache automatically expires after 24 hours, and you cannot modify this setting.", "After a file expires, the next time the edge location gets a user request for the file, CloudFront forwards the request to the origin server.", "When the origin receives a request, the origin sends the latest version of the file regardless of whether it is the same as the expired version in the cache.", "You can control cache file duration with CloudFront cache policy settings or through Cache-Control settings in the origin file headers. However, you cannot combine these options."], "answers": ["After a file expires, the next time the edge location gets a user request for the file, CloudFront forwards the request to the origin server."]}, {"id": "Development-m9-q9", "course": "Development", "module": 9, "prompt": "Which use case suggests the use of Amazon CloudFront Functions?", "options": ["A function that redirects the viewer to a different URL and adds a custom response header", "A function that uses a third-party library", "A function that requires network access to use external services for processing", "A function that requires access to the body of HTTP requests."], "answers": ["A function that redirects the viewer to a different URL and adds a custom response header"]}, {"id": "Development-m9-q10", "course": "Development", "module": 9, "prompt": "Which statement reflects a benefit of lazy loading as a caching strategy?", "options": ["Lazy loading avoids filling up the cache with data that is not requested.", "With lazy loading, data in the cache never becomes stale.", "With lazy loading, every write involves two trips--a write to the cache and a write to the database--which adds latency to the process.", "Lazy loading might result in a cache churn. The cache might be updated often if certain records are updated repeatedly."], "answers": ["Lazy loading avoids filling up the cache with data that is not requested."]}, {"id": "Development-m10-q1", "course": "Development", "module": 10, "prompt": "Which option describes how a message queue processes messages?", "options": ["The queue polls producers for new messages.", "Consumer poll the queue for messages.", "The queue broadcasts messages to consumer.", "Consumer notify the queue when a message has been successfully processed. The queue configuration determines whether the message should be available to other consumers."], "answers": ["Consumer poll the queue for messages."]}, {"id": "Development-m10-q2", "course": "Development", "module": 10, "prompt": "Which option describes how publish/subscribe (pub/sub) messaging works?", "options": ["Producers send messages to subscribers.", "Subscribers poll topics for new messages.", "When a topic receives a new message, the topic sends the message to the first subscriber who responds to a notification.", "A new topic message is pushed out to all topic subscribers."], "answers": ["A new topic message is pushed out to all topic subscribers."]}, {"id": "Development-m10-q3", "course": "Development", "module": 10, "prompt": "A developer wants to add an Amazon Simple Queue Service (Amazon SQS) queuq to decouple incoming order requests from a backend database. Which Amazon SQS operations might be part of this update?", "options": ["Use the SendMessage operation with the QueueURL mapped to the database endpoint to put messages on the queue.", "Use the ReceiveMessage operation with MaxNumberOfMessages set to 5 to retrieve up to 5 messages off the queue at one time.", "Use the DeleteMessage operation to change the visibility of the message as soon as the ReceiptHandle is received.", "Use the RecieveMessage operation with the WaitTimeSeconds parameter set to 0 to reduce the number of empty requests."], "answers": ["Use the ReceiveMessage operation with MaxNumberOfMessages set to 5 to retrieve up to 5 messages off the queue at one time."]}, {"id": "Development-m10-q4", "course": "Development", "module": 10, "prompt": "A tester reports that Amazon Simple Queue Service (Amazon SQS) messages are being processed more than once. The developer finds that processing servers are not completing as quickly as expected, and messages are made available to other consumers before the prior consumer deletes them. Which option might reduce occurrences of this issue?", "options": ["Increase the visibility timeout.", "Increase maxReceiveCount.", "Increase MaxNumberOfMessages.", "Increase the number of producers on the queue."], "answers": ["Increase the visibility timeout."]}, {"id": "Development-m10-q5", "course": "Development", "module": 10, "prompt": "For an order-processing application that uses an Amazon Simple Queue Service (Amazon SQS) queue, a developer finds that an older version of the client generates order records that fail the backend process. The failures cause a bottleneck on the queue. How might the developer reduce the impact of the failed records?", "options": ["Increase the visibility timeout and set a high value for MaxNumberOfMessages.", "Add a dead-letter queue and set a low maxRecieveCount.", "Use long polling and set a high wait time.", "Change the queue type from standard to First-In-First-Out (FIFO) and set a high throughput rate."], "answers": ["Add a dead-letter queue and set a low maxRecieveCount."]}, {"id": "Development-m10-q6", "course": "Development", "module": 10, "prompt": "Which statement about Amazon Simple Queue Service (Amazon SQS) polling options is true?", "options": ["By default, when you make a ReceiveMessage API call, Amazon SQS performs long polling.", "When long polling is configured, WaitTimeSeconds is set to 0.", "When short polling is configured, Amazon SQS queries all of its servers.", "When short polling is configured, Amazon SQS samples a subset of its servers."], "answers": ["When short polling is configured, Amazon SQS samples a subset of its servers."]}, {"id": "Development-m10-q7", "course": "Development", "module": 10, "prompt": "Which statement about Amazon Simple Notification Service (Amazon SNS) is true?", "options": ["An SNS topic is a logical access point, which acts as a communication channel.", "A publisher can only send messages to topics that they have created.", "By default, different subscribers to a topic receive different messages.", "Amazon SNS defines a single delivery policy, which is applied to all delivery protocols."], "answers": ["An SNS topic is a logical access point, which acts as a communication channel."]}, {"id": "Development-m10-q8", "course": "Development", "module": 10, "prompt": "An Amazon Simple Notification Service (Aamzon SNS) topic receives messages about orders. An AWS Lambda function that processes canceled orders is subscribed to the topic. How might the developer reduce costs by only invoking the Lambda function for canceled orders?", "options": ["Put an Amazon Simple Queue Service (Amazon SQS) queue in front of the Lambda function.", "Separate the new order and cancel order messages to be sent by two different publishers.", "Set up a filter policy so that the Lambda function subscription only receives cancel order messages.", "Use the ConfirmSubscription operation to limit which messages the Lambda function receives."], "answers": ["Set up a filter policy so that the Lambda function subscription only receives cancel order messages."]}, {"id": "Development-m10-q9", "course": "Development", "module": 10, "prompt": "A developer needs to build a custom application to put customer application log records onto an Amazon Kinesis data stream. What should they use to build the application?", "options": ["Use the Kinesis API.", "Use the Kinesis Producer Library (KPL).", "Use the Kinesis Client Library (KCL).", "Use Amazon Kinesis Data Analytics."], "answers": ["Use the Kinesis Producer Library (KPL)."]}, {"id": "Development-m10-q10", "course": "Development", "module": 10, "prompt": "Which statement about Amazon Kinesis Data Streams is true?", "options": ["When a record is added to the stream, the record is available until a consumer deletes it.", "The data records in a data stream are distributed into shards.", "A standard data stream can have one consumer. With the enhanced fanout option, you can add multiple consumers.", "A stream consumer must delete the records that it processes successfully."], "answers": ["The data records in a data stream are distributed into shards."]}, {"id": "Development-m11-q1", "course": "Development", "module": 11, "prompt": "Which scenario suggests the need for a task coordination service such as AWS Step Functions?", "options": [], "answers": ["A serverless application must run a series of AWS Lambda Functions that are dependent on each other"]}, {"id": "Development-m11-q2", "course": "Development", "module": 11, "prompt": "Which statement describes a benefit of using AWS Step Functions for an application?", "options": ["Step Functions integrates with state machines so that developers can transition between their Step Functions workflow and their state machine workflow", "Step Functions can be configured Amazon...", "Step Functions can be defined by using either Python or Node.js", "Developers can use Step Functions to build visual workflows"], "answers": ["Developers can use Step Functions to build visual workflows"]}, {"id": "Development-m11-q3", "course": "Development", "module": 11, "prompt": "What is the role of the Task state type in AWS Step Functions?", "options": ["Task states are used to stop a failed workflow", "Task states perform a unit of work", "Task states provide branching logic", "Task states tell the state machine the order to perform the steps in"], "answers": ["Task states perform a unit of work"]}, {"id": "Development-m11-q4", "course": "Development", "module": 11, "prompt": "An application that processes order returns must complete different steps depending on whether the return is within 30 days of purchase. Which AWS Step Functions state could a developer use to implement this logic?", "options": ["Parallel", "Task", "Choice", "Wait"], "answers": ["Choice"]}, {"id": "Development-m11-q5", "course": "Development", "module": 11, "prompt": "An application that processes order returns must run the same AWS Lambda function for each item in an order. Which AWS Step Function could a developer use to implement this logic?", "options": ["Parallel", "Pass", "Map", "Task"], "answers": ["Map"]}, {"id": "Development-m11-q6", "course": "Development", "module": 11, "prompt": "Which statement is true for both Succeed states and Fail states?", "options": ["Succeed states and Fail states do not include the Next field", "The End field is not required because Succeed states and Fail states are not terminal states", "The Type field is optional for Succeed states and Fail states", "The End field is required because Succeed states and Fail states are terminal states"], "answers": ["Succeed states and Fail states do not include the Next field"]}, {"id": "Development-m11-q7", "course": "Development", "module": 11, "prompt": "An application that processes order returns must run two independent audits checks. When both checks are successfully completed, the return authorization step is run. Which AWS Step Functions state could a developer use to implement this logic?", "options": ["Parallel", "Task", "Choice", "Wait"], "answers": ["Parallel"]}, {"id": "Development-m11-q8", "course": "Development", "module": 11, "prompt": "How is a taskToken used in an AWS Step Functions use case that includes a manual approval step?", "options": ["A taskToken is generated when the workflow hits a Wait state. The taskToken tracks how long the workflow has been waiting for a task to finish.", "A taskToken is used to transition between each state in the workflow and is defined in the Next field", "A taskToken is returned as part of a call to the GetActivityTask action and is used when calling the SendTaskSuccess action to associate a result with a task", "A taskToken is an output of the Success state in a synchronous Step Functions Express workflow. A taskToken is used to confirm success of all tasks"], "answers": ["A taskToken is returned as part of a call to the GetActivityTask action and is used when calling the SendTaskSuccess action to associate a result with a task"]}, {"id": "Development-m11-q9", "course": "Development", "module": 11, "prompt": "Which use case is a good fit for AWS Step Functions Express workflows?", "options": ["All workflows in the application must be auditable up to 90 days after a completed run", "The workflow requires a step that will run an application that is hosted on an Amazon Elastic Compute Cloud (Amazon EC2) instance", "The workflow takes between 30 minutes and 1 hour to run", "The workflow must support a very high rate of events that come from Internet of Things(IoT) devices"], "answers": ["The workflow must support a very high rate of events that come from Internet of Things(IoT) devices"]}, {"id": "Development-m11-q10", "course": "Development", "module": 11, "prompt": "Which statement about AWS Step Functions is true?", "options": ["A developer can use Amazon API Gateway to associate their Step Function APIs with methods in an API Gateway API", "Step Functions has quotas at the account level regarding the number of registered state machines, but no quotas are related to individual Step Functions runs", "Step Functions must be created in the visual editor on the Step Functions console but can be edited with the AWS SDKs", "A developer can use the Describe API action to get a summary of all state machines and the number of times that each has been run"], "answers": ["A developer can use Amazon API Gateway to associate their Step Function APIs with methods in an API Gateway API"]}, {"id": "Development-m12-q1", "course": "Development", "module": 12, "prompt": "Which statement about creating secure connections is true?", "options": ["Both Secure Sockets Layer (SSL) and Transport Layer Security (TLS) are standards that AWS developed for secure communications.", "SSL uses certificates to establish website identity, but TLS does not.", "Both SSL and TLS encrypt network communications between connected resources.", "SSL is a newer version of TLS. Both are used to establish the identify of websites."], "answers": ["Both SSL and TLS encrypt network communications between connected resources."]}, {"id": "Development-m12-q2", "course": "Development", "module": 12, "prompt": "Which step in the secure connection process is the responsibility of the certificate authority (CA)?", "options": ["Issue a certificate.", "Verify whether the certificate is from a trusted source.", "Send an encrypted session key.", "Send a certificate and public key to the client."], "answers": ["Issue a certificate."]}, {"id": "Development-m12-q3", "course": "Development", "module": 12, "prompt": "Which statement about AWS Certificate Manager (ACM) is true?", "options": ["ACM can provision public certificates, but for private certificates, developers must produce their own certificate and connect it to ACM.", "ACM manages certificate renewals for both public and private certificates.", "ACM costs are based on the number of active public certificates in an AWS account.", "A developer must configure a load balancer to use ACM certificates."], "answers": ["ACM manages certificate renewals for both public and private certificates."]}, {"id": "Development-m12-q4", "course": "Development", "module": 12, "prompt": "Which statement reflects a best practice for security credentials?", "options": ["Only share access keys between users in the same AWS account.", "Use AWS Identity and Access Management (IAM) roles to retrieve temporary security credentials.", "If there are unencrypted access keys, embed them in code that is available only to developers but not accessible to users.", "Do not allow programmatic authentication to AWS services."], "answers": ["Use AWS Identity and Access Management (IAM) roles to retrieve temporary security credentials."]}, {"id": "Development-m12-q5", "course": "Development", "module": 12, "prompt": "What is the primary difference between AWS Security Token Service (AWS STS) authentication by federated users and AWS STS authentication by AWS Identity and Access Management (IAM) users?", "options": ["With federated users, the application calls an identity broker, but this step is skipped with IAM users.", "With federated users, the first authentication is made against an IdP. With IAM users, the first authentication is made against IAM.", "With federated users, the second authentication is made against an IdP. With IAM users, the second authentication is made against IAM", "With federated users, applications use the temporary security credentials and token to make requests to an AWS service. No token is necessary with IAM users."], "answers": ["With federated users, the first authentication is made against an IdP. With IAM users, the first authentication is made against IAM."]}, {"id": "Development-m12-q6", "course": "Development", "module": 12, "prompt": "A developer has been asked to investigate how website files have been deleted from an Amazon Simple Storage Service (Amazon S3) bucket. Which approach should they take?", "options": ["Use AWS CloudTrail to search for information about delete object events on the S3 bucket.", "Use AWS Security Token Service (AWS STS) to block deletions from the S3 bucket.", "Use AWS Identity and Access Management (IAM) to search for users who have used their delete permissions on the S3 bucket.", "Use the AWS STS GetSessionToken API call to retrieve information about users who deleted files from the S3 bucket."], "answers": ["Use AWS CloudTrail to search for information about delete object events on the S3 bucket."]}, {"id": "Development-m12-q7", "course": "Development", "module": 12, "prompt": "A developer has been asked to add a sign-up and sign-in service to their application. Which Amazon Cognito feature should they use?", "options": ["Amazon Cognito identity pool", "Amazon Cognito user pool", "Amazon Cognito Lambda trigger", "Amazon Cognito access token"], "answers": ["Amazon Cognito user pool"]}, {"id": "Development-m12-q8", "course": "Development", "module": 12, "prompt": "A developer has been asked to reduce the security risk of users who sign in to their application with username and password pairs that they use on other websites. Which Amazon Cognito user pool feature might the developer configure?", "options": ["Identity tokens", "Phone and email verification", "Adaptive authentication", "Compromised credentials check"], "answers": ["Compromised credentials check"]}, {"id": "Development-m12-q9", "course": "Development", "module": 12, "prompt": "Which statement about Amazon Cognito identity pools is true?", "options": ["With an identity pool. users can obtain temporary, limited-privilege AWS credentials to access other AWS services.", "Identity pools replace the need for a third-party identity provider.", "When using Amazon Cognito identity pools, a user would not also use Amazon Cognito user pools.", "Identity pools provide sign-up and sign-in functionality for mobile apps."], "answers": ["With an identity pool. users can obtain temporary, limited-privilege AWS credentials to access other AWS services."]}, {"id": "Development-m12-q10", "course": "Development", "module": 12, "prompt": "A developer plans to use Amazon Cognito user pools with Amazon API Gateway. Which step is part of the user pool authentication flow with API Gateway?", "options": ["A mobile app sends a request to API Gateway, and API Gateway gets JSON Web Tokens (JWTs) from the user pool.", "A mobile app user authenticates with a user pool, and the user pool returns JWTs to the app.", "The user pool validates the tokens against an identity pool.", "Amazon Cognito invokes the API after successfully validating the permissions."], "answers": ["A mobile app user authenticates with a user pool, and the user pool returns JWTs to the app."]}, {"id": "Development-m13-q1", "course": "Development", "module": 13, "prompt": "Which option describes the philosophy of DevOps?", "options": [], "answers": ["DevOps is about removing barriers between development and operations functions to optimize productivity and reliability"]}, {"id": "Development-m13-q2", "course": "Development", "module": 13, "prompt": "How are DevOps practices reflected in the software development lifecycle for cloud architectures?", "options": [], "answers": ["Every phase of the software development is automated."]}, {"id": "Development-m13-q3", "course": "Development", "module": 13, "prompt": "How might a developer use AWS CodePipeline in their continuous integration continuous deployment (CI/CD) process?", "options": [], "answers": ["Automate the steps that are required to release software based on a release model that the developer defines."]}, {"id": "Development-m13-q4", "course": "Development", "module": 13, "prompt": "Which statement about continuous integration and continuous delivery/deployment (CI/CD) is true?", "options": [], "answers": ["Continuous integration requires teams to write the automated tests."]}, {"id": "Development-m13-q5", "course": "Development", "module": 13, "prompt": "A developer wants to use infrastructure as code for their java-based web application on AWS. Which task might be part of their work?", "options": [], "answers": ["Create an AWS CloudFormation template with a Resources section that defines the AWS resources for the application."]}, {"id": "Development-m13-q6", "course": "Development", "module": 13, "prompt": "A developer wants to use a single AWS CloudFormation template for both the test and production environments. Which section of the template might they use to support this approach?", "options": [], "answers": ["Use the Conditions section to control whether certain resources are created during stack creation or update."]}, {"id": "Development-m13-q7", "course": "Development", "module": 13, "prompt": "Which statement about AWS CloudFormation stacks is true?", "options": [], "answers": ["A CloudFormation stack is a unit of deployment."]}, {"id": "Development-m13-q8", "course": "Development", "module": 13, "prompt": "A developer is building their first serverless application on AWS. What must they think about differently with respect to deploying the application.", "options": [], "answers": ["They can't replicate the production environment locally in the same way that they might with a server-based deployment"]}, {"id": "Development-m13-q9", "course": "Development", "module": 13, "prompt": "How does an AWS Serverless Application Model (AWS SAM) template differ from an AWS CloudFormation template?", "options": [], "answers": ["The Globals section is only found in AWS SAM templates"]}, {"id": "Development-m13-q10", "course": "Development", "module": 13, "prompt": "The following lines are in the Resources section of an AWS Serverless Application Model (AWS SAM) template. What would these lines create? Resources: Orders: Type: AWS::Serverless::Simple Table", "options": [], "answers": ["An Amazon DynamoDB Table that is called Orders."]}, {"id": "Foundations-m1-q1", "course": "Foundations", "module": 1, "prompt": "What are the advantages of cloud computing over computing on-premises?", "options": [], "answers": ["Avoid large capital purchases", "Use on-demand capacity", "Increase speed and agility"]}, {"id": "Foundations-m1-q2", "course": "Foundations", "module": 1, "prompt": "What is the pricing model that enables AWS customers to pay for resources on an as-needed basis?", "options": [], "answers": ["Pay as you go"]}, {"id": "Foundations-m1-q3", "course": "Foundations", "module": 1, "prompt": "Which of these is NOT a cloud computing model? (Select the best answer.)", "options": [], "answers": ["System administration as a service"]}, {"id": "Foundations-m1-q4", "course": "Foundations", "module": 1, "prompt": "True of False? AWS owns and maintains the network-connected hardware required for\n\n       application services, while you provision and use what you need.", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m1-q5", "course": "Foundations", "module": 1, "prompt": "Which of these is not a benefit of cloud computing over on-premises computing?", "options": [], "answers": ["Pay for racking, stacking, and powering services"]}, {"id": "Foundations-m1-q6", "course": "Foundations", "module": 1, "prompt": "Which of the following are not benefits of AWS Cloud computing?", "options": [], "answers": ["High Latency", "Multiple procurement cycles"]}, {"id": "Foundations-m1-q7", "course": "Foundations", "module": 1, "prompt": "Which of the following is a compute service? (Select the best answer)", "options": [], "answers": ["Amazon EC2"]}, {"id": "Foundations-m1-q8", "course": "Foundations", "module": 1, "prompt": "True or False? Cloud Computing provides a simple way to access servers, storage, databases, and\n\n       a broad set of application services over the internet. You own the network-connected  hardware required for these services and Amazon Web Services provisions what you need.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m1-q9", "course": "Foundations", "module": 1, "prompt": "Economics of Scale result from_______", "options": [], "answers": ["having hundreds of thousands of customers aggregated in cloud"]}, {"id": "Foundations-m1-live-q10", "course": "Foundations", "module": 1, "prompt": "Which of these are ways to access AWS core services? (Choose three.)", "options": [], "answers": ["AWS Management Console", "AWS Command Line Interface (AWS CLI)", "Software Development Kits (SDKs)"]}, {"id": "Foundations-m2-q1", "course": "Foundations", "module": 2, "prompt": "For certain services like Amazon Elastic Compute Cloud (Amazon EC2) and\n\n       Amazon Relational Database Service (Amazon RDS), you can invest in reserved capacity.\n       What options are available for Reserved Instances?", "options": [], "answers": ["AURI", "NURI", "PURI"]}, {"id": "Foundations-m2-q2", "course": "Foundations", "module": 2, "prompt": "Where can a customer go to get more details about Amazon Elastic Compute Cloud\n       (Amazon EC2) billing activity that took the place 3 months ago?", "options": [], "answers": ["AWS Cost Explorer"]}, {"id": "Foundations-m2-q3", "course": "Foundations", "module": 2, "prompt": "True or false? To receive the discounted rate associated with Reserved Instances, you must\n        make a full, upfront payment for the term of the agreement", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m2-q4", "course": "Foundations", "module": 2, "prompt": "There is no charge for which of the following?", "options": [], "answers": ["Inbound data transfer (with some exceptions)", "Data transfer between services within the same AWS Reg"]}, {"id": "Foundations-m2-live-q4", "course": "Foundations", "module": 2, "prompt": "Which statement is true about the pricing model on AWS? (Select the best answer.)", "options": [], "answers": ["Storage is typically charged per gigabyte."]}, {"id": "Foundations-m2-q5", "course": "Foundations", "module": 2, "prompt": "What are the four support plans offered by AWS Support?", "options": [], "answers": ["Basic, Developer, Business, Enterprise"]}, {"id": "Foundations-m2-q6", "course": "Foundations", "module": 2, "prompt": "What AWS tool compares the cost of running your application in an on-premises data\n       center to AWS?", "options": [], "answers": ["Total Cost of Ownership (TCO) calculator"]}, {"id": "Foundations-m2-live-q6", "course": "Foundations", "module": 2, "prompt": "What AWS tool lets you explore AWS services and create an estimate for the cost of your use cases on AWS? (Select the best answer.)", "options": [], "answers": ["AWS Pricing Calculator"]}, {"id": "Foundations-m2-q7", "course": "Foundations", "module": 2, "prompt": "As AWS grows, the cost of doing business is reduced and savings are passed back to the\n      customer with lower pricing. What is this optimization called?", "options": [], "answers": ["Economics of scale"]}, {"id": "Foundations-m2-q8", "course": "Foundations", "module": 2, "prompt": "True or false? AWS offers a variety of services at no charge, for example, Amazon Virtual Private Cloud (Amazon VPC), AWS Identity and Access Management (IAM),\n       Consolidated Billing, AWS Elastic Beanstalk, automatic scaling, AWS Ops Works and\n       AWS CloudFormation. However, you might be charged for other AWS services that you use\n       in conjunction with these services", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m2-q9", "course": "Foundations", "module": 2, "prompt": "When are free data transfers applicable across AWS?", "options": [], "answers": ["Free inbound data transfer for Amazon Elastic Computer Cloud (Amazon EC2) instances", "Free outbound data transfer between AWS services within the same Region"]}, {"id": "Foundations-m2-live-q9", "course": "Foundations", "module": 2, "prompt": "What are benefits of using AWS Organizations? (Choose two.)", "options": [], "answers": ["Provides the ability to create groups of accounts and then attach policies to a group", "Simplifies automating account creation and management by using APIs"]}, {"id": "Foundations-m2-q10", "course": "Foundations", "module": 2, "prompt": "True of false? Unlimited services are available with the AWS Free Tier to new AWS customers for 12 months following their AWS sign-up date.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m3-q1", "course": "Foundations", "module": 3, "prompt": "Which component of the AWS Global Infrastructure does Amazon CloudFront use to ensure low-latency delivery? (Select the best answer)", "options": ["AWS Regions", "AWS Edge locations", "AWS Availability Zone", "Amazon virtual private cloud (Amazon VPC)"], "answers": ["AWS Edge locations"]}, {"id": "Foundations-m3-q2", "course": "Foundations", "module": 3, "prompt": "You can run applications and workloads from a region closer to the end users to ______ latency.", "options": ["Increase", "Decrease"], "answers": ["Decrease"]}, {"id": "Foundations-m3-q3", "course": "Foundations", "module": 3, "prompt": "True / False? Networking, storage, compute and databases are examples of service categories\n\n       that AWS offers.", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m3-q4", "course": "Foundations", "module": 3, "prompt": "Which of these statements about Availability Zones is not true? (Select the best answer)", "options": ["Availability Zones are designed for fault isolation", "Availability Zones are made up of one or more data centers", "Availability zones are connected to each other using high-speed private links", "A data center can be used for more than one availability zone"], "answers": ["A data center can be used for more than one availability zone"]}, {"id": "Foundations-m3-q5", "course": "Foundations", "module": 3, "prompt": "What is true about Regions (Choose two)", "options": ["They are the physical locations of your customers", "All regions are located in one specific geographic area", "A region is a physical location that has multiple availability zones", "Physical location has multiple availability zones", "Each region is located in a separate geographic area"], "answers": ["A region is a physical location that has multiple availability zones", "Each region is located in a separate geographic area"]}, {"id": "Foundations-m3-q6", "course": "Foundations", "module": 3, "prompt": "Which of the following are geographic areas that host two or more Availability Zones? (Select the best answer)", "options": ["AWS Origin", "AWS Regions", "Compute Zones", "Edge Locations"], "answers": ["AWS Regions"]}, {"id": "Foundations-m3-q7", "course": "Foundations", "module": 3, "prompt": "_____ means the infrastructure has built-in component redundancy and _____ means that resources dynamically adjust to increases or decreases in capacity requirements.", "options": ["No human intervention, fault-tolerant", "Fault-tolerant, no human intervention", "Elastic and scalable, fault-tolerant", "Elastic and scalable, no human intervention", "Fault-tolerant, elastic and scalable"], "answers": ["Fault-tolerant, elastic and scalable"]}, {"id": "Foundations-m3-q8", "course": "Foundations", "module": 3, "prompt": "True or False? Availability Zones within a region are connected through low-latency links.", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m3-q9", "course": "Foundations", "module": 3, "prompt": "AWS highly recommends provisioning your compute resources across _____ availability zones.", "options": ["All", "No", "Multiple", "Single"], "answers": ["Multiple"]}, {"id": "Foundations-m3-q10", "course": "Foundations", "module": 3, "prompt": "True or False? Edge locations are only located in the same general area as regions.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m4-q1", "course": "Foundations", "module": 4, "prompt": "In the shared responsibility model, AWS is responsible for providing what? (Select the best answer.)", "options": [], "answers": ["Security of the Cloud"]}, {"id": "Foundations-m4-q2", "course": "Foundations", "module": 4, "prompt": "In the shared responsibility model, which of the following are examples of \" Security in the cloud\" ?", "options": ["Compliance with compute security standards and regulations.", "Physical security of the facilities in which the service operates.", "Security group configurations.", "Encryption of the data at rest and data in transit.", "Protecting the global infrastructure."], "answers": ["Security group configurations.", "Encryption of the data at rest and data in transit."]}, {"id": "Foundations-m4-q3", "course": "Foundations", "module": 4, "prompt": "Which of the following is the responsibility of AWS under the AWS shared responsibility model? (Select the best answer).", "options": ["Configuring third party applications.", "Maintaining physical hardware.", "Security application access and data.", "Managing custom Amazon machine images (AMI's)."], "answers": ["Maintaining physical hardware."]}, {"id": "Foundations-m4-q4", "course": "Foundations", "module": 4, "prompt": "When creating an AWS Identity and Access Management (IAM) policy, what are the two types of access that can be granted to a user? (Choose two).", "options": ["Institutuional Access.", "Authorized Access.", "Programmatic Access.", "AWS Management Console Access.", "Administrative Root Access."], "answers": ["Programmatic Access.", "AWS Management Console Access."]}, {"id": "Foundations-m4-q5", "course": "Foundations", "module": 4, "prompt": "True or false? AWS organizations enables you to consolidate multiple aws accounts so that\n\n       you centrally manage them.\n\n           True.\n\n           False.", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m4-q6", "course": "Foundations", "module": 4, "prompt": "Which of the following are best practices to secure your account using aws identity and access management? (Choose 2).", "options": ["Provide users with default administrative privileges.", "Leave unused and unnecessary users and credentials in place.", "Manage access to AWS resources.", "Avoid using IAM groups to grant the same access permissions to multiple users.", "Define fine-grained access rights."], "answers": ["Manage access to AWS resources.", "Define fine-grained access rights."]}, {"id": "Foundations-m4-q7", "course": "Foundations", "module": 4, "prompt": "Which of the following should be done by the AWS account root user? (Select the best answer).", "options": ["Secure access for applications.", "Integrate with other AWS services.", "Change granular permissions.", "Change the AWS support plan."], "answers": ["Change the AWS support plan."]}, {"id": "Foundations-m4-q8", "course": "Foundations", "module": 4, "prompt": "After initial login, what does AWS recommend as the best practice for the AWS account root user?", "options": ["Delete the AWS account root user.", "Revoke all permissions on the AWS account root user.", "Restrict permission on the AWS account root user.", "Delete the access keys of the AWS account root user."], "answers": ["Delete the access keys of the AWS account root user."]}, {"id": "Foundations-m4-q9", "course": "Foundations", "module": 4, "prompt": "How would a system administrator add an additional layer of login security to a user's AWS management console?", "options": ["Use Amazon Cloud Directory.", "Audit AWS Identity and Access Management (IAM) roles.", "Enable multi-factor authentication.", "Enable AWS CloudTrail."], "answers": ["Enable multi-factor authentication."]}, {"id": "Foundations-m4-q10", "course": "Foundations", "module": 4, "prompt": "True or false? AWS key management service (AWS KMS) enables you to assess, audit,\n\n         and evaluate the configurations of your AWS resources.\n\n             True.\n\n             False.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m5-q1", "course": "Foundations", "module": 5, "prompt": "Which AWS networking service enables a company to create a virtual network within AWS", "options": ["AWS Config", "Amazon Route 53", "AWS Direct Connect", "Amazon VPC"], "answers": ["Amazon VPC"]}, {"id": "Foundations-m5-q2", "course": "Foundations", "module": 5, "prompt": "With Amazon Virtual Private Cloud (Amazon VPC), what is the smallest size subnet you can have in a VPC?", "options": ["/28", "/30", "/24", "/26"], "answers": ["/28"]}, {"id": "Foundations-m5-q3", "course": "Foundations", "module": 5, "prompt": "With Amazon Virtual Private Cloud (Amazon VPC), what is the maximum size IP address range you can have in a VPC?", "options": ["/28", "/16", "/30", "/24"], "answers": ["/16"]}, {"id": "Foundations-m5-q4", "course": "Foundations", "module": 5, "prompt": "You need to allow resources in a private subnet to access the internet. Which of the following must be present to enable this access?", "options": ["Network access control lists", "Security groups", "NAT gateway", "Route tables"], "answers": ["NAT gateway"]}, {"id": "Foundations-m5-q5", "course": "Foundations", "module": 5, "prompt": "Which AWS networking service enables a company to create a virtual network within AWS?", "options": ["Amazon Virtual Private Cloud (Amazon VPC)", "AWS Direct Connect", "Amazon Route 53", "AWS Config"], "answers": ["Amazon Virtual Private Cloud (Amazon VPC)"]}, {"id": "Foundations-m5-q7", "course": "Foundations", "module": 5, "prompt": "T/F, Private subnets have direct access to the internet.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m5-q8", "course": "Foundations", "module": 5, "prompt": "Which component of AWS Global Infrastructure does Amazon CloudFront use to ensure low-latency deliver?", "options": ["AWS Regions", "AWS Availability Zones", "AWS edge locations", "Amazon Virtual Private Cloud (Amazon VPC)"], "answers": ["AWS edge locations"]}, {"id": "Foundations-m5-q9", "course": "Foundations", "module": 5, "prompt": "Which of the following is an optional security control that can be applied at the subnet layer of a VPC?", "options": ["Network ACL", "Security group", "Web application firewall", "Firewall"], "answers": ["Network ACL"]}, {"id": "Foundations-m5-q10", "course": "Foundations", "module": 5, "prompt": "What happens when you use Amazon Virtual Private Cloud (Amazon VPC) to create a new VPC?", "options": ["Three subnets are created by default in one Availability Zone", "A main route table is created by default", "Three subnets are created by default: one for each Availability Zone", "An internet gateway is created by default."], "answers": ["A main route table is created by default"]}, {"id": "Foundations-m5-q11", "course": "Foundations", "module": 5, "prompt": "Which of the following can be used to protect Amazon Elastic Compute Cloud (Amazon EC2)  instances hosted in AWS?", "options": ["Internet Gateway", "All of the above", "AMI", "Security group"], "answers": ["Security group"]}, {"id": "Foundations-m5-q12", "course": "Foundations", "module": 5, "prompt": "You are a solutions architect who works at a large retail company that is migrating its existing infrastructure to AWS. You recommend that they use a custom VPC. When you create a VPC, you assign it to an IPv4 Classless Inter-Domain Routing (CIDR) block of 10.0.1.0/24 (which has 256 total IP addresses). How many IP addresses are available?", "options": ["251", "256", "246", "250"], "answers": ["251"]}, {"id": "Foundations-m6-q1", "course": "Foundations", "module": 6, "prompt": "Why is AWS more economical than traditional data centers for applications with varying compute workloads? (Select the best answer).", "options": ["Amazon EC2 Costs are billed on a monthly basis.", "Customers retain full administrative access to their Amazon EC2 instances.", "Customers can permanently run enough instances to handle peak workloads.", "Amazon EC2 instances can be launched on-demand when needed."], "answers": ["Amazon EC2 instances can be launched on-demand when needed."]}, {"id": "Foundations-m6-q2", "course": "Foundations", "module": 6, "prompt": "If your project requires monthly reports that iterate through very large amounts of data, which Amazon Elastic Compute Cloud EC2 purchasing option should you consider? (Select the best answer).", "options": ["Spot Instances.", "Scheduled Reserved Instances.", "Dedicated Hosts.", "On-Demand Instances."], "answers": ["Scheduled Reserved Instances."]}, {"id": "Foundations-m6-q3", "course": "Foundations", "module": 6, "prompt": "What is included in an Amazon Machine Image (AMI)? Select the best answer.", "options": ["A template for the root volume for the instance.", "Launch permissions that control which AWS accounts can use the AMI to launch instances.", "A block device mapping that specifies the volumes to attach to the instance when it's launched.", "All of the above."], "answers": ["All of the above."]}, {"id": "Foundations-m6-q4", "course": "Foundations", "module": 6, "prompt": "Which Amazon Elastic Compute Cloud EC2 feature ensures your instances will not share a physical host with instances from any other AWS customer? (Select the best answer).", "options": ["Amazon VPC.", "Placement Groups.", "Dedicated Instances.", "Reserved Instances."], "answers": ["Dedicated Instances."]}, {"id": "Foundations-m6-q5", "course": "Foundations", "module": 6, "prompt": "Which of the following services is a serverless compute service in AWS? (Select the best answer).", "options": ["AWS Config.", "AWS Lambda.", "AWS OpsWork.", "Amazon EC2."], "answers": ["AWS Lambda."]}, {"id": "Foundations-m6-q6", "course": "Foundations", "module": 6, "prompt": "What is the service provided by AWS that enables developers to easily deploy and manage applications in the cloud? (Select the best answer).", "options": ["Amazon Elastic Container Service.", "AWS Elastic Beanstalk.", "AWS OpsWork", "AWS CloudFormation"], "answers": ["AWS Elastic Beanstalk."]}, {"id": "Foundations-m6-q7", "course": "Foundations", "module": 6, "prompt": "Your web application needs four instances to support steady traffic all of the time. On the last day of the month, the traffic triples. What is the most cost-effective way to handle this pattern?  (Select the best answer).", "options": ["Run 12 reserved instances all of the time.", "Run four On-demand Instances constantly, then add eight more On-Demand on the last day of each month.", "Run four Reserved Instances constantly, then add eight On-Demand Instances on the last day of each month.", "Run four On-Demand Instances constantly, then add eight Reserved Instances on the last day of each month."], "answers": ["Run four Reserved Instances constantly, then add eight On-Demand Instances on the last day of each month."]}, {"id": "Foundations-m6-q8", "course": "Foundations", "module": 6, "prompt": "True or false? Containers contain an entire operating system.\n\nTrue.\nFalse.", "options": ["True", "False"], "answers": ["False"]}, {"id": "Foundations-m6-q9", "course": "Foundations", "module": 6, "prompt": "Which Amazon EC2 option is best for long-term workload with predictable usage patterns? (Select the best answer).", "options": ["Spot Instances.", "On-Demand Instances.", "Reserved Instances."], "answers": ["Reserved Instances."]}, {"id": "Foundations-m6-q10", "course": "Foundations", "module": 6, "prompt": "Which of the following must be specified when launching a new Amazon Elastic Cloud Compute EC2 windows instance? (Choose two).", "options": ["Amazon EC2 instance type.", "Amazon Machine Image (AMI).", "The Amazon EC2 Instance ID.", "Password for the administrator account.", "Amazon EC2 instance type."], "answers": ["Amazon Machine Image (AMI).", "Amazon EC2 instance type."]}, {"id": "Foundations-m7-q1", "course": "Foundations", "module": 7, "prompt": "True or false. Amazon simple storage service S3 is an object storage suitable for the storage    of flat files like Microsoft Word documents, photos, etc.", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m7-q2", "course": "Foundations", "module": 7, "prompt": "Amazon S3 replicates all objects _____. (Select the best answer).", "options": ["On multiple volumes within an availability zone.", "In multiple Availability zones within the same region.", "Across multiple regions for higher durability.", "On multiple S3 buckets."], "answers": ["In multiple Availability zones within the same region."]}, {"id": "Foundations-m7-q3", "course": "Foundations", "module": 7, "prompt": "Which of the following can be used as a storage class for an S3 object lifecycle policy?", "options": ["S3 Standard Access.", "AWS Storage Gateway.", "S3 Infrequent Access.", "Simple Storage Service Glacier.", "S3 Reduced Redundancy Storage.", "Amazon Dynamo DB."], "answers": ["Simple Storage Service Glacier.", "S3 Infrequent Access.", "S3 Standard Access."]}, {"id": "Foundations-m7-q4", "course": "Foundations", "module": 7, "prompt": "The name of an S3 bucket must be unique.", "options": ["Worldwide across all AWS accounts.", "Within a region.", "Across all your AWS accounts.", "Within your AWS account."], "answers": ["Worldwide across all AWS accounts."]}, {"id": "Foundations-m7-q5", "course": "Foundations", "module": 7, "prompt": "You can use amazon elastic file system efc to: (Select the best answer).", "options": ["Provide simple, scalable, elastic file storage for use only within AWS.", "Implement storage for Amazon EC2 instances that multiple virtual machines can access at the same time.", "Host a robust CDN to deliver entire web sites with dynamic, static, and streaming content.", "Generate user specific content."], "answers": ["Implement storage for Amazon EC2 instances that multiple virtual machines can access at the same time."]}, {"id": "Foundations-m7-q6", "course": "Foundations", "module": 7, "prompt": "Amazon Elastic Block Storage (Amazon EBS) is recommended when data _____ and ______ (Choose two).", "options": ["Requires object level storage.", "Must be quickly accessbile, requiring long-term persistence.", "Requires an encryption solution.", "Needs to be stored in a different availability zone than the one the EC2 instance is in."], "answers": ["Must be quickly accessbile, requiring long-term persistence.", "Requires an encryption solution."]}, {"id": "Foundations-m7-q7", "course": "Foundations", "module": 7, "prompt": "True or false, by default all data stored in amazon S3 is viewable by the public.", "options": ["True.", "False."], "answers": ["False."]}, {"id": "Foundations-m7-q8", "course": "Foundations", "module": 7, "prompt": "Regarding amazon S3 glacier, what is a vault?", "options": ["The rules that determine who may (or may not) access archives.", "An object (photos, videos, files, or documents).", "A container for storing archives.", "A policy that identifies who can access content stored in Glacier."], "answers": ["A container for storing archives."]}, {"id": "Foundations-m7-q9", "course": "Foundations", "module": 7, "prompt": "True or false. When you create a bucket in amazon S3, it is associated with a specific aws region.", "options": ["True.", "False."], "answers": ["True."]}, {"id": "Foundations-m7-q10", "course": "Foundations", "module": 7, "prompt": "Which of the following are features of Amazon Elastic Block Store (Amazon EBS). (Choose two).", "options": ["Data on an Amazon EBS volume is lost when the attatched instance is stopped.", "Amazon EBS volumes can be encrypted transparently to workloads on the attached instance.", "Amazon EBS data is automatically backed up to tape.", "Data stored on Amazon EBS is automatically replicated within an Availability Zone."], "answers": ["Amazon EBS volumes can be encrypted transparently to workloads on the attached instance.", "Data stored on Amazon EBS is automatically replicated within an Availability Zone."]}, {"id": "Foundations-m8-q1", "course": "Foundations", "module": 8, "prompt": "You are designing an ecommerce web application that will scale to hundreds of thousands of concurrent users, Which database technology is best suited to hold the session state in this example?", "options": ["Amazon Relational Database Service (Amazon RDS)", "Amazon DynamoDB", "Amazon RedShift", "Amazon Simple Storage (Amazon S3)"], "answers": ["Amazon DynamoDB"]}, {"id": "Foundations-m8-q2", "course": "Foundations", "module": 8, "prompt": "You need to find an item in Amazon DynamoDB table using an attribute other than item's primary key. Which of the following operations should you use?", "options": ["Put Item", "Scan", "Query", "Get Item"], "answers": ["Scan"]}, {"id": "Foundations-m8-q3", "course": "Foundations", "module": 8, "prompt": "In Amazon DynamoDB, what does the query operation enable you to do?", "options": ["Query a table using the Partition Key and optional sort key filter", "Query and secondary indexes that exists for a table", "Efficiency retrieve items from a table or secondary index", "All the Above"], "answers": ["All the Above"]}, {"id": "Foundations-m8-q4", "course": "Foundations", "module": 8, "prompt": "Which AWS Cloud service is best suited for analyzing your data by using standard structured  query language (SQL) and your existing business intelligence (BI) tools", "options": ["Amazon Relational Database (Amazon RDS)", "Amazon Simple Storage Simple Glacier", "Amazon Dynamo DB", "Amazon Redshift"], "answers": ["Amazon Redshift"]}, {"id": "Foundations-m8-q5", "course": "Foundations", "module": 8, "prompt": "In Amazon DynamoDB, an attribute is________.", "options": ["A Fundamental Data Element", "A Collection Of items", "A Collection of Attributes"], "answers": ["A Fundamental Data Element"]}, {"id": "Foundations-m8-q6", "course": "Foundations", "module": 8, "prompt": "Which of the following use cases is appropriate for using Amazon Relational Database Service (Amazon RDS)?", "options": ["Massive read / write rates", "Simple Gets or Put Requests", "Complex Transactions", "All the Above"], "answers": ["Complex Transactions"]}, {"id": "Foundations-m8-q7", "course": "Foundations", "module": 8, "prompt": "A company has an application, which consists of a .NET layer that connects to a MySQL database. They want to move this application on to AWS and use AWS features such as high availability and automated backups. Which of the following would be an ideal database for this use case ( Select the best answer)", "options": ["Amazon Dynamo DB", "Amazon RDS", "Amazon Aurora", "Amazon Redshift"], "answers": ["Amazon Aurora"]}, {"id": "Foundations-m8-q8", "course": "Foundations", "module": 8, "prompt": "If you are developing an application that requires a database with extremely fast performance, fast scalability, and flexibility in the database schema, which service would you consider?", "options": ["Amazon Relational Database (Amazon RDS)", "Amazon Elastic Cache", "Amazon Dynamo DB", "Amazon Redshift"], "answers": ["Amazon Dynamo DB"]}, {"id": "Foundations-m8-q9", "course": "Foundations", "module": 8, "prompt": "True of false? Amazon RDS automatically patches the database software and backs up your database, storing the backups for a user-defined retention period and enabling point-in- time recovery", "options": ["True", "False"], "answers": ["True"]}, {"id": "Foundations-m8-q10", "course": "Foundations", "module": 8, "prompt": "What should you consider when choosing database type?", "options": ["Data Size", "Data access period", "Query Frequency", "All the Above", "Highly Available"], "answers": ["All the Above"]}, {"id": "Foundations-m9-q1", "course": "Foundations", "module": 9, "prompt": "Which of the following is not one of the four areas of the Performance Efficiency pillar of the AWS Well-Architected Framework?", "options": ["Tradeoffs", "Selection", "Traceability", "Monitoring"], "answers": ["Traceability"]}, {"id": "Foundations-m9-q2", "course": "Foundations", "module": 9, "prompt": "Which of the following is a principle when designing cloud-based systems?", "options": ["Build tightly - coupled components", "Make infrequent , large batch changes", "Assume Everything will fail", "Use as many services as possible"], "answers": ["Assume Everything will fail"]}, {"id": "Foundations-m9-q3", "course": "Foundations", "module": 9, "prompt": "Which of the following are pillars of the AWS Well-Architected Framework? (Choose three)", "options": ["Security", "Persistence", "Operational Excellence", "Cost Optimization"], "answers": ["Security", "Operational Excellence", "Cost Optimization"]}, {"id": "Foundations-m9-q4", "course": "Foundations", "module": 9, "prompt": "Which design principles are recommended when considering performance efficiency? (Choose 2)", "options": ["Enable traceability", "Use serverless architecture", "Analyze and attribute expenditure", "Match Supply with demand", "Democratize advance technologies"], "answers": ["Use serverless architecture", "Democratize advance technologies"]}, {"id": "Foundations-m9-q5", "course": "Foundations", "module": 9, "prompt": "AWS Trusted Advisor provides insight regarding which five categories of an AWS account?", "options": ["Performance, cost optimization, security, fault tolerance, service limits.", "Security, Fault tolerance, high availability, connectivity, service limits", "Performance, cost optimization, access control, connectivity, security", "Security, access control, high availability, performance, service limits"], "answers": ["Performance, cost optimization, security, fault tolerance, service limits."]}, {"id": "Foundations-m9-q6", "course": "Foundations", "module": 9, "prompt": "What is the focus of the sustainability pillar of the Well-Architected Framework? (Select the best answer.)", "options": ["Designing workloads that recover quickly from failures.", "Minimizing the environmental impacts of running cloud workloads", "Avoiding unnecessary costs in cloud workloads", "Automating updates to cloud workloads"], "answers": ["Minimizing the environmental impacts of running cloud workloads"]}, {"id": "Foundations-m9-q7", "course": "Foundations", "module": 9, "prompt": "The AWS Well-Architected Framework is organized into how many pillars?", "options": [], "answers": ["6"]}, {"id": "Foundations-m9-q8", "course": "Foundations", "module": 9, "prompt": "After you move to the AWS Cloud, you want to ensure that the right security settings are put in place. Which online tool can assist in security compliance?", "options": ["Amazon Kinesis", "Amazon Support", "AWS Trusted Advisor", "Amazon Cloud watch"], "answers": ["AWS Trusted Advisor"]}, {"id": "Foundations-m9-q9", "course": "Foundations", "module": 9, "prompt": "Which of the following is a measure of your system's ability to provide functionality when desired by the user?", "options": ["Availability", "Fault Tolerance", "Reliability", "Performance Efficiency"], "answers": ["Reliability"]}, {"id": "Foundations-m9-q10", "course": "Foundations", "module": 9, "prompt": "What is defined as the ability for a system to remain operational even if some of the components of that system fail?", "options": ["High durability", "Fault Tolerance", "High availability"], "answers": ["Fault Tolerance"]}, {"id": "Foundations-m9-q11", "course": "Foundations", "module": 9, "prompt": "Which of the following best describes a system that can withstand some measures of degradation, experiences minimal downtime, and requires minimal human intervention", "options": ["Scalable", "Fault Tolerant", "Elastic", "Highly available"], "answers": ["Highly available"]}, {"id": "Foundations-m10-q1", "course": "Foundations", "module": 10, "prompt": "Which of the following AWS tools help your application scale up or down based on demand?", "options": ["Availability Zones", "Amazon EC2 Auto Scaling", "Aws CloudFormation", "Elastic load balancing", "AWS Config"], "answers": ["Amazon EC2 Auto Scaling", "Elastic load balancing"]}, {"id": "Foundations-m10-q2", "course": "Foundations", "module": 10, "prompt": "Which service would you use to send alerts based on Amazon CloudWatch alarms?", "options": ["Amazon Simple Notification Service (Amazon SNS)", "AWS Cloud Trail", "AWS Trusted Advisor", "Amazon Route 53"], "answers": ["Amazon Simple Notification Service (Amazon SNS)"]}, {"id": "Foundations-m10-q3", "course": "Foundations", "module": 10, "prompt": "Which of the following are characteristics of Amazon EC2 Auto Scaling? ( Choose three )", "options": ["Only Supports Dynamic Scaling", "Responds to changing conditions by adding or terminating instances", "Deliver Push Notifications", "Launches instances from a specified Amazon Machine Image (AMI)", "Enforces a minimum number of running Amazon EC2 instances"], "answers": ["Responds to changing conditions by adding or terminating instances", "Launches instances from a specified Amazon Machine Image (AMI)", "Enforces a minimum number of running Amazon EC2 instances"]}, {"id": "Foundations-m10-q4", "course": "Foundations", "module": 10, "prompt": "Which of the following must be configured on an Elastic Load Balancing load balancer to expect incoming traffic ?", "options": ["A Port", "A Network Interface", "A Listener", "An Instance"], "answers": ["A Listener"]}, {"id": "Foundations-m10-q5", "course": "Foundations", "module": 10, "prompt": "Which of the following elements are used to create an Amazon EC2 Auto Scaling launch configuration?", "options": ["Amazon Machine Image (AMI)", "Load Balancer", "Instance type", "Virtual Private Cloud (VPC ) and Subnets", "Amazon Elastic Block Store (Amazon EBS) volumes"], "answers": ["Amazon Machine Image (AMI)", "Instance type", "Amazon Elastic Block Store (Amazon EBS) volumes"]}, {"id": "Foundations-m10-q6", "course": "Foundations", "module": 10, "prompt": "Which of the following services can help you conflict important metrics from Amazon Relational Database Service (Amazon RDS) and Amazon Elastic Compute Cloud (Amazon EC2) instances?", "options": ["Amazon CloudFront", "Amazon Cloud Search", "Amazon Cloud Watch", "Amazon Cloud Trial", "Amazon E2C Scaling"], "answers": ["Amazon Cloud Watch"]}, {"id": "Foundations-m10-q7", "course": "Foundations", "module": 10, "prompt": "Which of the following are elements of an Auto Scaling group ? (Choose three)", "options": ["Maximum size", "Health Checks", "Desired capacity", "Minimum size"], "answers": ["Maximum size", "Desired capacity", "Minimum size"]}, {"id": "Foundations-m10-q8", "course": "Foundations", "module": 10, "prompt": "There is an adult at your company and they need to have a big log of all access to AWS resources in the account. Which of the following services can assist in providing these details?", "options": ["Amazon Cloud Watch", "AWS CloudTrail", "Amazon Elastic Compute Cloud (Amazon EC2)", "Amazon Simple Notification Service ( Amazon SNS)"], "answers": ["AWS CloudTrail"]}, {"id": "Foundations-m10-q9", "course": "Foundations", "module": 10, "prompt": "In Elastic Load Balancing, when the load balancing detects an unhealthy target, which of the following are true (Choose three)", "options": ["Stops routing traffic to that target", "Triggers an Alarm", "Resumes routing traffic when it detects that the target is healthy again", "Resumes routing traffic when manually restarted", "Routes traffic to a healthy target"], "answers": ["Stops routing traffic to that target", "Resumes routing traffic when it detects that the target is healthy again", "Routes traffic to a healthy target"]}, {"id": "Foundations-m10-live-q10", "course": "Foundations", "module": 10, "prompt": "What are the three types of load balancers that Elastic Load Balancing offers?", "options": ["Internet Load Balancer", "Application Load Balancer", "Network Load Balancer", "Compute Load Balancer", "Classic Load Balancer", "Auto Scaling Load Balancer"], "answers": ["Application Load Balancer", "Network Load Balancer", "Classic Load Balancer"]}];
